    if file_name != suffix:
        return False
    if not parent_rel:
        return False
    for collection in workflow.collections.values():
        prefix = collection.path.split("*")[0].rstrip("/")
        pattern = f"{prefix}/*" if prefix else "*"
        if path_matches_collection_pattern(parent_rel, pattern):
            return True
    return False


