def create_experiment_branch_and_worktree(
    source_repo_root: Path,
    branch_name: str,
    worktree_path: Path,
    base_commit: str,
) -> Path:
    worktree_path.parent.mkdir(parents=True, exist_ok=True)
    run_git(
        source_repo_root,
        "worktree",
        "add",
        "-b",
        branch_name,
        str(worktree_path),
        base_commit,
    )
    return worktree_path


def remove_partial_experiment_worktree(
    source_repo_root: Path,
    branch_name: str,
    worktree_path: Path,
) -> None:
