        check=False,
    )
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip()
        raise ExperimentLandError(
            f"Failed to push experiment branch {branch_name!r} to {remote!r}"
            + (f": {detail}" if detail else "")
        )


