    source_repo_root: Path,
    experiment_dir: Path,
    project: str,
    quest_type: str,
    quest_number: int,
    experiment_number: int,
) -> str:
    rel = experiment_dir.resolve().relative_to(source_repo_root.resolve()).as_posix()
    run_git(source_repo_root, "add", "--", rel)
    message = (
        f"experiment-create: {project}/{quest_type}/"
